import math
        import random
        import time

        LANGUAGE_WRAPPER = 'In a math contest, let x, y, z, c be nonnegative real numbers. For the given positive integers {u0}, {tau}, {c_coeff}, and {d_coeff}, determine the minimum value of the expression\nE(x,y,z,c) = (({u0} + x^2)({u0} + y^2)({u0} + z^2) * {tau} (1 + c^2)) / ((x + y + z)({c_coeff} c + {d_coeff})).\nGive your answer in simplest radical form.'

        class _RNGShim:
    def __init__(self, seed: int):
        import random as _random
        self._seed = int(seed)
        self._r = _random.Random(self._seed)

    def random(self): return self._r.random()
    def uniform(self, a, b): return self._r.uniform(a, b)
    def randint(self, a, b): return self._r.randint(a, b)
    def randrange(self, *args): return self._r.randrange(*args)
    def choice(self, seq): return self._r.choice(seq)
    def choices(self, population, weights=None, cum_weights=None, k: int = 1):
        return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
    def sample(self, population, k: int): return self._r.sample(population, k)
    def shuffle(self, x):
        self._r.shuffle(x)
        return x
    def getrandbits(self, k: int): return self._r.getrandbits(k)

        def generator(rng):
    # use rng.* for randomness
    # Choose parameters to avoid trivialities and ensure interior minima
    u0 = rng.randint(2, 12)          # u0 >= 2
    tau = rng.randint(2, 9)          # tau >= 2 for nontrivial scaling
    c_coeff = rng.randint(1, 9)      # C >= 1
    d_coeff = rng.randint(1, 9)      # D >= 1
    # Ensure (C,D) not both equal to 1 always; but any positive works. Still, avoid C=1,D=1 too often by resampling 20% of time.
    if (c_coeff == 1 and d_coeff == 1 and rng.random() < 0.5):
        c_coeff = rng.randint(2, 9)
    return {
        'u0': u0,
        'tau': tau,
        'c_coeff': c_coeff,
        'd_coeff': d_coeff
    }

        import math

def verifier(assign):
    # Validate presence and types
    for k in ['u0', 'tau', 'c_coeff', 'd_coeff']:
        if k not in assign:
            # Missing slot
            return (False, None)
        if not isinstance(assign[k], int):
            return (False, None)
    u0 = assign['u0']
    tau = assign['tau']
    C = assign['c_coeff']
    D = assign['d_coeff']
    # Domain validation
    if u0 <= 0 or tau <= 0 or C <= 0 or D <= 0:
        return (False, None)
    # Compute the exact minimal value symbolically as a formatted string and numerically for internal check
    # Part 1 (x,y,z): min over x,y,z>0 of ((u0+x^2)(u0+y^2)(u0+z^2))/(x+y+z)
    # Occurs at x=y=z= sqrt(u0/5); value = (72*sqrt(5)/125) * u0^(5/2)
    xyz_factor_num = 72
    xyz_factor_den = 125
    xyz_rad_inside = 5 * u0
    # Numeric value for x,y,z part
    xyz_min_val = (xyz_factor_num/xyz_factor_den) * math.sqrt(5.0) * (u0**2) * math.sqrt(u0)
    # Part 2 (c): min over c>=0 of tau*(1+c^2)/(C c + D)
    # Minimizer c* = ( -D + sqrt(C^2 + D^2) ) / C; minimum value = tau * 2 (sqrt(C^2 + D^2) - D) / C^2
    s = math.sqrt(C*C + D*D)
    c_min_val = tau * (2.0 * (s - D) / (C*C))
    total_min_val = xyz_min_val * c_min_val
    # Build exact-form string with radicals
    # Exact expression: (144 * tau * u0^2)/(125 * C^2) * sqrt(5*u0) * (sqrt(C^2 + D^2) - D)
    A = 144 * tau * (u0**2)
    B = 125 * (C**2)
    S2 = C*C + D*D
    ans_str = f"\\frac{{{A}}}{{{B}}}\\,\\sqrt{{{5*u0}}}\\,\\big(\\sqrt{{{S2}}}-{D}\\big)"
    # As a sanity check, ensure positivity and nontriviality
    if not (total_min_val > 0):
        return (False, None)
    # Return True and the exact-answer string
    return True, ans_str


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
                        "assignment": assignment,
                        "question": question,
                        "answer": answer,
                        "attempts": attempts,
                        "elapsed_seconds": time.time() - start,
                    }
            raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")
